import{_ as l,l as i,o as e,c as s,v as o,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"锁顺序","description":"","frontmatter":{"title":"锁顺序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lock-ordering.md","filePath":"cs/lock-ordering.md","lastUpdated":1789023840000}'),h={name:"cs/lock-ordering.md"};function _(m,a,f,u,A,k){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="锁顺序" tabindex="-1">锁顺序 <a class="header-anchor" href="#锁顺序" aria-label="Permalink to &quot;锁顺序&quot;">​</a></h1><div class="epigraph"><p>对所有锁规定一个全序，任何路径只能按升序获取：循环等待被静态拆掉，这是内核里最常用的死锁预防。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, LKD 对锁层级的整理</footer></div><p><a href="/cs/livelock-starvation">上一课</a>把活锁与饥饿从环上拆走。<a href="/cs/deadlock-prevent">预防与避免</a>点过锁排序。<a href="/cs/deadlock-coffman">Coffman</a> 的第四条是循环等待。缺口是把工程纪律写死：<strong>锁顺序</strong>——每把锁一个层级号，获取时号必须上升；需要反序则先放掉已持有的。本课收同步课主干，不进入地址空间布局。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两把 mutex 在不同文件里各看起来正确，组合出 AB-BA。银行家要配额，检测有滞后。排序：规定 <code>lock_A</code> 先于 <code>lock_B</code>，所有调用方遵守，则等待图不可能出现 A←B←A。缺口不是再定义四条件，而是这份<strong>全序与校验</strong>（运行时锁依赖图、注释里的层级）。</p><p><span class="marginnote">同层多把锁（多对象）还要规定二级序：例如按地址从低到高拿，以免两个对象之间成环。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给锁分类：调度队列锁、内存描述符锁、inode 锁……文档写层级。获取：只能向上。不得不向下：释放到分叉点再按序重拿，可能需要重试（注意与活锁：重试要有进展或退避）。IRQ 上下文只允许某层以上的自旋，与<a href="/cs/lock-irq">锁与关中断</a> 一致。锁依赖检测：记录当前任务持有的锁，新获取若与已持有的历史边成环则报警。</p>',8)),(e(),n(p,null,{default:r(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E5%B1%82%E7%BA%A71%22%5D%20--%3E%20L2%5B%22%E5%B1%82%E7%BA%A72%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E5%B1%82%E7%BA%A73%22%5D%0A%20%20BAD%5B%22%E5%8F%8D%E5%BA%8F%E8%8E%B7%E5%8F%96%22%5D%20--%3E%20DL%5B%22%E5%8F%AF%E8%83%BD%E6%88%90%E7%8E%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 RCU：读侧无锁，不进这张序；写者仍要遵守保护该结构的互斥锁序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>锁顺序把预防做成可审查的规范，适合内核这种长期演进的代码。它不解决饥饿，不解决活锁，也不自动给出 PI。违反序是缺陷，即使测试没撞上死锁。用户程序同样可用：对全局锁集合编号。动态创建的锁用地址序当全序的一种。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux <code>lockdep</code> 的全部类写成调试手册，不讨论如何故意构造死锁。虚存布局、brk、缺页是下一课程单元；页表锁也要进全局序，但对象换成分页。同步课到此结束。</p><p>后课默认：多锁必须有全序。用户地址空间里代码、堆、栈如何摆，下一课<a href="/cs/addrspace-layout">地址空间布局</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>锁全序破坏循环等待，是内核主要的死锁预防。</li><li>同层对象按地址等二级序；反序必须先释放。</li><li>不处理饥饿与活锁；下一单元进入虚存布局。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',8))])}const b=l(h,[["render",_]]);export{E as __pageData,b as default};
